package org.fantazia.rp3d;
import org.junit.Test;
import static org.junit.Assert.*;
public class UrlPolicyTest {
 @Test public void productionDefaults(){assertEquals("https://fantazia-rp-3d1.onrender.com/",MainActivity.DEFAULT_SERVER);assertEquals(MainActivity.DEFAULT_SERVER,UrlPolicy.validate(MainActivity.DEFAULT_SERVER));assertEquals(120000,MainActivity.CONNECTION_TIMEOUT_MS);assertFalse(UrlPolicy.sameOrigin("https://fantazia-rp-3d1-pr-5.onrender.com/",MainActivity.DEFAULT_SERVER));}
 @Test public void normalize(){assertEquals("https://game.example.org/",UrlPolicy.validate(" https://GAME.example.org/index.html "));assertEquals("https://game.example.org/",UrlPolicy.validate("https://game.example.org:443/"));assertEquals("https://game.example.org:8443/",UrlPolicy.validate("https://game.example.org:8443"));}
 @Test public void rejectUnsafe(){for(String raw:new String[]{"",null,"http://game.example.org","file:///secret","intent://game","https://localhost/","https://127.0.0.1/","https://127.1/","https://[::1]/","https://user:pass@game.example.org/","https://game.example.org/?token=x","https://game.example.org/#x","https://game.example.org/admin","https://game.example.org:70000/","https://host.local/","https://game.example.org./"}){try{UrlPolicy.validate(raw);fail(String.valueOf(raw));}catch(IllegalArgumentException expected){}}}
 @Test public void origins(){String base="https://game.example.org/";assertTrue(UrlPolicy.sameOrigin(base+"page",base));assertTrue(UrlPolicy.sameOrigin("https://game.example.org:443/page",base));for(String raw:new String[]{"http://game.example.org","https://game.example.org.evil.org/","https://game.example.org:8443/","file:///","https://user@game.example.org/"})assertFalse(raw,UrlPolicy.sameOrigin(raw,base));}
 @Test public void microphone(){assertTrue(UrlPolicy.audioOnly(new String[]{"android.webkit.resource.AUDIO_CAPTURE"}));assertFalse(UrlPolicy.audioOnly(null));assertFalse(UrlPolicy.audioOnly(new String[]{}));assertFalse(UrlPolicy.audioOnly(new String[]{"android.webkit.resource.VIDEO_CAPTURE"}));assertFalse(UrlPolicy.audioOnly(new String[]{"android.webkit.resource.AUDIO_CAPTURE","android.webkit.resource.VIDEO_CAPTURE"}));}
}
